#include <stdio.h>

int main(void) {
    for (int i = 0; i < 3; i++) {
        printf("%d\n", i);
    }
    return 0;
}

#include <stdio.h>

int add(int a, int b) {
    return a + b;
}

int main(void) {
    printf("%d\n", add(2, 3));
    return 0;
}

#include <stdio.h>

int main(void) {
    int x = 5;
    int *p = &x;
    *p = 10;
    printf("%d\n", x);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

int main(void) {
    int *nums = malloc(3 * sizeof(int));
    nums[0] = 7;
    printf("%d\n", nums[0]);
    free(nums);
    return 0;
}

#include <stdio.h>

struct Point {
    int x;
    int y;
};

int main(void) {
    struct Point p = {1, 2};
    printf("%d, %d\n", p.x, p.y);
    return 0;
}

#include <stdio.h>
#include <string.h>

int main(void) {
    char name[] = "Ada";
    printf("%s has %zu letters\n", name, strlen(name));
    return 0;
}
